/* A lightweight, 30 fps weather layer. No animation over the reading surface. */
class WinterWeather {
 constructor(canvas){this.canvas=canvas;this.context=canvas.getContext('2d');this.enabled=false;this.frame=0;this.chapter=0;this.mode='home';this.last=0;this.seed=213;this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.resize=()=>{this.width=innerWidth;this.height=innerHeight;const scale=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(this.width*scale);canvas.height=Math.round(this.height*scale);this.context.setTransform(scale,0,0,scale,0,0);this.particles=Array.from({length:Math.min(125,Math.round(this.width/17))},()=>this.particle());};addEventListener('resize',this.resize);document.addEventListener('visibilitychange',()=>this.run());this.resize();}
 random(){this.seed=(this.seed*1664525+1013904223)>>>0;return this.seed/4294967296;}
 particle(){return{x:this.random()*this.width,y:this.random()*this.height,r:.45+this.random()*1.5,v:10+this.random()*23,drift:3+this.random()*15,phase:this.random()*6.28,alpha:.12+this.random()*.38};}
 configure(enabled,chapter=0,mode='home'){this.enabled=!!enabled&&!this.reduced.matches;this.chapter=chapter;this.mode=mode;this.canvas.dataset.weather=chapter===3?'blizzard':chapter===2?'window':'snow';this.run();}
 run(){cancelAnimationFrame(this.frame);if(!this.enabled||document.hidden){this.context.clearRect(0,0,this.width,this.height);return;}this.last=0;this.frame=requestAnimationFrame(t=>this.draw(t));}
 draw(time){this.frame=requestAnimationFrame(t=>this.draw(t));if(this.last&&time-this.last<32)return;const dt=this.last?Math.min((time-this.last)/1000,.07):.033;this.last=time;const context=this.context;context.clearRect(0,0,this.width,this.height);const storm=this.chapter===3?2.2:1;for(const p of this.particles){p.y+=p.v*storm*dt;p.x+=(p.drift*storm+Math.sin(time*.0004+p.phase)*8)*dt;if(p.y>this.height+8){p.y=-8;p.x=this.random()*this.width;}if(p.x>this.width+8)p.x=-8;context.beginPath();context.fillStyle=`rgba(229,231,226,${p.alpha*(this.mode==='reader'?.6:.85)})`;context.ellipse(p.x,p.y,p.r,p.r*(this.chapter===3?1.7:1),-.45,0,Math.PI*2);context.fill();}}
}
window.WinterWeather=WinterWeather;
